import React from 'react';

export default function PuppiesView({ puppies, activeFilters, updateFilter, showPuppyDetail, setCurrentView }) {
  const filteredPuppies = puppies.filter(puppy => {
    const matchWhere = activeFilters.where === 'Everywhere' || puppy.where === activeFilters.where;
    const matchBreed = activeFilters.breeds.length === 0 || activeFilters.breeds.includes(puppy.breed);
    const matchGender = activeFilters.genders.length === 0 || activeFilters.genders.includes(puppy.gender);
    return matchWhere && matchBreed && matchGender;
  });

  const isBtnActive = (type, val) => {
    if (type === 'where') return activeFilters.where === val;
    if (type === 'breed') return activeFilters.breeds.includes(val);
    if (type === 'gender') return activeFilters.genders.includes(val);
    return false;
  };

  return (
    <main className="fade-in puppies-container">
      <h2>Available puppies</h2>
      <p className="puppies-desc">
        Every listing shows real photos of the actual puppy. Open a profile to see them all, then ask us about them on WhatsApp.
      </p>

      <div className="filters-box">
        <div className="filter-row">
          <span className="filter-label">where</span>
          <div className="filter-btns">
            {['Everywhere', 'Imported', 'Korean Teacup', 'Dubai'].map(loc => (
              <button key={loc} onClick={() => updateFilter('where', loc)} className={`filter-btn ${isBtnActive('where', loc) ? 'active' : ''}`}>{loc}</button>
            ))}
          </div>
        </div>
        <div className="filter-row">
          <span className="filter-label">breed</span>
          <div className="filter-btns">
            {['Maltipoo', 'Pomeranian', 'Poodle', 'Cavapoo', 'Shih Tzu'].map(breed => (
              <button key={breed} onClick={() => updateFilter('breed', breed)} className={`filter-btn ${isBtnActive('breed', breed) ? 'active' : ''}`}>{breed}</button>
            ))}
          </div>
        </div>
        <div className="filter-row">
          <span className="filter-label">boy or girl</span>
          <div className="filter-btns">
            {['Boy', 'Girl'].map(gender => (
              <button key={gender} onClick={() => updateFilter('gender', gender)} className={`filter-btn ${isBtnActive('gender', gender) ? 'active' : ''}`}>{gender}s</button>
            ))}
          </div>
        </div>
      </div>

      <p className="puppy-count"><span>{filteredPuppies.length}</span> puppies looking for a home</p>

      {filteredPuppies.length === 0 ? (
        <div className="empty-state">No puppies match your exact filters. Try clearing some!</div>
      ) : (
        <div className="puppy-grid">
          {filteredPuppies.map(puppy => (
            <div key={puppy.id || puppy._id} onClick={() => showPuppyDetail(puppy.id || puppy._id)} className="puppy-card">
              <div className="pc-image-wrapper">
                <div className="pc-bg" style={{ backgroundColor: puppy.colorBg }}></div>
                <div className="pc-badge">🐾 Available</div>
                <div className="pc-img-container">
                  <img src={puppy.image} alt={puppy.breed} />
                </div>
              </div>
              <h3 className="pc-name font-serif">{puppy.name}</h3>
              <p className="pc-breed-gender">{puppy.breed} • {puppy.gender}</p>
              <p className="pc-meta">{puppy.where} • {puppy.age}</p>
            </div>
          ))}
        </div>
      )}

      {/* NEW: ALREADY GONE HOME BANNER (Using structural inline styles for guaranteed rendering) */}
      <div style={{ backgroundColor: '#f4ebd9', borderRadius: '2rem', padding: '3rem 2rem', marginTop: '5rem', display: 'flex', flexDirection: 'column', gap: '3rem', alignItems: 'center' }}>

        {/* Banner Text */}
        <div style={{ textAlign: 'center', maxWidth: '30rem' }}>
          <h2 className="font-serif" style={{ fontSize: '3rem', marginBottom: '0.5rem', lineHeight: '1.1', color: '#4a3b32' }}>Already gone home</h2>
          <p style={{ fontSize: '1.125rem', marginBottom: '1.5rem', color: 'rgba(74, 59, 50, 0.8)' }}>These puppies have found their families.</p>
          <button className="btn-primary" onClick={() => setCurrentView('gone-home')}>
            See the puppies who've gone home
          </button>
        </div>

        {/* Banner Images in Rounded Squares */}
        <div style={{ display: 'flex', gap: '1.5rem', flexWrap: 'wrap', justifyContent: 'center' }}>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <img src="https://images.unsplash.com/photo-1589287707312-0afebf984b55?auto=format&fit=crop&w=200&q=80" alt="Ace" style={{ width: '100px', height: '100px', borderRadius: '1rem', objectFit: 'cover', border: '3px solid #4a3b32' }} />
            <span style={{ background: 'white', border: '2px solid #4a3b32', borderRadius: '999px', fontSize: '0.7rem', padding: '2px 10px', marginTop: '-12px', zIndex: 2, fontWeight: 'bold', color: '#8c4a2f', whiteSpace: 'nowrap' }}>gone home ♥</span>
            <span className="font-serif" style={{ fontWeight: 'bold', fontSize: '1.125rem', marginTop: '4px', color: '#4a3b32' }}>Ace</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <img src="https://images.unsplash.com/photo-1598133894008-61f7fec39e71?auto=format&fit=crop&w=200&q=80" alt="Leo" style={{ width: '100px', height: '100px', borderRadius: '1rem', objectFit: 'cover', border: '3px solid #4a3b32' }} />
            <span style={{ background: 'white', border: '2px solid #4a3b32', borderRadius: '999px', fontSize: '0.7rem', padding: '2px 10px', marginTop: '-12px', zIndex: 2, fontWeight: 'bold', color: '#8c4a2f', whiteSpace: 'nowrap' }}>gone home ♥</span>
            <span className="font-serif" style={{ fontWeight: 'bold', fontSize: '1.125rem', marginTop: '4px', color: '#4a3b32' }}>Leo</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <img src="https://images.unsplash.com/photo-1579621970563-ebec7560ff3e?auto=format&fit=crop&w=200&q=80" alt="Mia" style={{ width: '100px', height: '100px', borderRadius: '1rem', objectFit: 'cover', border: '3px solid #4a3b32' }} />
            <span style={{ background: 'white', border: '2px solid #4a3b32', borderRadius: '999px', fontSize: '0.7rem', padding: '2px 10px', marginTop: '-12px', zIndex: 2, fontWeight: 'bold', color: '#8c4a2f', whiteSpace: 'nowrap' }}>gone home ♥</span>
            <span className="font-serif" style={{ fontWeight: 'bold', fontSize: '1.125rem', marginTop: '4px', color: '#4a3b32' }}>Mia</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <img src="https://images.unsplash.com/photo-1601979031925-424e53b6caaa?auto=format&fit=crop&w=200&q=80" alt="Sadie" style={{ width: '100px', height: '100px', borderRadius: '1rem', objectFit: 'cover', border: '3px solid #4a3b32' }} />
            <span style={{ background: 'white', border: '2px solid #4a3b32', borderRadius: '999px', fontSize: '0.7rem', padding: '2px 10px', marginTop: '-12px', zIndex: 2, fontWeight: 'bold', color: '#8c4a2f', whiteSpace: 'nowrap' }}>gone home ♥</span>
            <span className="font-serif" style={{ fontWeight: 'bold', fontSize: '1.125rem', marginTop: '4px', color: '#4a3b32' }}>Sadie</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <img src="https://images.unsplash.com/photo-1537151608804-ea2aa1427189?auto=format&fit=crop&w=200&q=80" alt="Pomeranian" style={{ width: '100px', height: '100px', borderRadius: '1rem', objectFit: 'cover', border: '3px solid #4a3b32' }} />
            <span style={{ background: 'white', border: '2px solid #4a3b32', borderRadius: '999px', fontSize: '0.7rem', padding: '2px 10px', marginTop: '-12px', zIndex: 2, fontWeight: 'bold', color: '#8c4a2f', whiteSpace: 'nowrap' }}>gone home ♥</span>
            <span className="font-serif" style={{ fontWeight: 'bold', fontSize: '1.125rem', marginTop: '4px', color: '#4a3b32' }}>Pomeranian</span>
          </div>

        </div>
      </div>
    </main>
  );
}
